contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test function: deposit and check balance did not decrease
    function runTest(uint256 deposit) public payable {
        // require this contract has enough balance to forward
        require(address(this).balance >= deposit);

        // record previous balance of this contract's address in C
        uint256 before = c.getBalance(address(this));

        // perform the deposit call on C — this changes C's state
        c.addToBalance{value: deposit}();

        // observe balance after deposit
        uint256 after = c.getBalance(address(this));

        // The invariant: after >= before and after >= deposit (captures that deposit does not reduce stored balance)
        // We assert that the reported balance increased by at least the deposited amount.
        assert(after >= before + deposit);
    }

    // allow funding this test contract
    receive() external payable {}
}

