contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint deposit) public payable {
        require(address(this).balance >= deposit && deposit > 0);
        // call addToBalance on c sending Ether 'deposit'
        bool reverted;
        try c.addToBalance{value: deposit}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint bal = c.getBalance(address(this));
