pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor, address other) public {
        // keep amount reasonable for fuzzing but allow zero
        amount = bound(amount, 0, address(this).balance + 1 ether);
        // avoid the zero address for actor to allow vm.prank to work sensibly
        vm.assume(actor != address(0));
        vm.assume(other != address(0));

        // record balances before
        uint256 beforeActor = c.getBalance(actor);
        uint256 beforeOther = c.getBalance(other);

        // fund the actor so they can send ETH
        vm.deal(actor, amount);
        // actor calls addToBalance sending `amount` wei
        vm.prank(actor);
        // call as payable
        (bool ok, ) = address(c).call{value: amount}(abi.encodeWithSignature("addToBalance()"));
        // treat failed call as not changing balances (the invariant concerns completed calls); we still observe state
        // record balances after
        uint256 afterActor = c.getBalance(actor);
        uint256 afterOther = c.getBalance(other);

        // General invariant: no account's stored userBalance decreases as a result of addToBalance
        // We assert it for both the caller and another arbitrary account
        assertTrue(afterActor >= beforeActor && afterOther >= beforeOther);
    }
}

