contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: payer address and amount to send
    function testFuzz_property(uint256 rawAmount, address payer) public {
        // keep amount in a practical range but wide enough to include large values
        uint256 amount = bound(rawAmount, 0, type(uint128).max);
        // disallow the zero-address as a caller for clarity
        vm.assume(payer != address(0));

