pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: attacker address and an amount to deposit.
    // The general property: after a successful addToBalance() call by actor, their balance increases exactly by the sent value.
    // We fuzz actor and amount so the fuzzer can find scenarios (with an adversarial helper) that break the buggy contract.
    function testFuzz_property(address actor, uint256 amount) public {
        // Keep actor non-zero and amount reasonable (but wide): at least 1 wei and not exceeding a large cap to avoid overflows in test harness.
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1 ether);

        // Deploy a malicious contract that will re-enter C during an external call if possible.
        // This attacker will, in its fallback/receive, call back into c.addToBalance() to try to disturb balances.
        Attacker attacker = new Attacker(c);

        // Fund the attacker so it can send the deposit.
        vm.deal(address(attacker), amount);

        // Record prior balance as seen by C for the attacker address.
        uint256 before = c.getBalance(address(attacker));

        // Have the attacker call addToBalance sending `amount` wei.
        // The attacker will forward the call from its own address so c sees msg.sender == attacker.
        // Use prank to make the call originate from attacker (so msg.sender in c is attacker contract address)
        vm.prank(address(attacker));
        // Call into c; if it reverts, we treat that as a failure of the property (but reference should never revert for valid inputs)
        bool ok;
        try c.addToBalance{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call, the property we assert: if the call succeeded, c.getBalance(attacker) == before + amount.
        // This is the single assertion reading c's public getter that the reference always satisfies and the mutant can violate.
        if (ok) {
            uint256 after = c.getBalance(address(attacker));
            assertTrue(after == before + amount);
        } else {
            // If addToBalance reverted, still assert false because reference should not revert here for valid inputs;
            // but to keep a single assertTrue as required, assert that ok is true (this will fail if revert happens).
            assertTrue(ok);
        }
    }
}

// Minimal attacker that re-enters during receive to try to exploit a bad reentrancy guard.
contract Attacker {
    C target;
    bool reentered;
    constructor(C _target) {
        target = _target;
        reentered = false;
    }
    // When receiving ETH, attempt to re-enter addToBalance once to disturb balances if the guard is faulty.
    receive() external payable {
        if (!reentered) {
            reentered = true;
            // try to call addToBalance again sending 0 value (just to re-enter and trigger any unsafe behavior)
            // Surround with try/catch to avoid bubbling failures to the outer call.
            try target.addToBalance{value: 0}() {
            } catch {
            }
        }
    }
}

