pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: attackerAmount is ETH sent by attacker when calling addToBalance;
    // victimInitial is an initial deposit by a victim address. The fuzzer will search values.
    function testFuzz_property(uint256 attackerAmount, uint256 victimInitial) public {
        // keep amounts in a reasonable range but wide enough
        attackerAmount = bound(attackerAmount, 1, 1 ether);
        victimInitial = bound(victimInitial, 1, 1 ether);

        // deploy two actors: victim and attacker helper (a reentrant attacker)
        address victim = address(0xBEEF);
        // fund victim and attacker externally
        vm.deal(victim, victimInitial);
        address attackerHelper = address(new ReentrantAttacker(c));
        vm.deal(attackerHelper, attackerAmount);

        // Victim deposits victimInitial to c
        vm.prank(victim);
        c.addToBalance{value: victimInitial}();

        // Record victim balance in contract before attacker acts
        uint256 beforeVictimBalance = c.getBalance(victim);

        // Attacker (the helper contract) will call addToBalance and attempt reentrancy
        // The attackerHelper's receive will reenter c.addToBalance during the external call
        ReentrantAttacker(attackerHelper).setTarget(address(c));

        // Make the attacker call addToBalance with attackerAmount
        // We use vm.prank to make the call originate from the helper contract so msg.sender in c is the helper
        vm.prank(attackerHelper);
        // call will send ETH from attackerHelper
        (bool ok, ) = address(c).call{value: attackerAmount}(abi.encodeWithSelector(c.addToBalance.selector));
        // we don't assert on ok here; we only assert the invariant below

        // EXACTLY ONE ASSERT: the reference contract guarantees that any addToBalance call that completes
        // does not change other users' balances; here we assert victim's balance stayed equal to beforeVictimBalance.
        // This holds for the reference implementation for all inputs; the mutant that disables the guard before
        // the body can allow reentrancy to modify victim's balance and thus violate this assertion for some inputs.
        assertTrue(c.getBalance(victim) == beforeVictimBalance);
    }
}

// adversarial helper: reentrantly calls addToBalance during receive()
contract ReentrantAttacker {
    C public target;

    constructor(C _t) payable {
        target = _t;
    }

    function setTarget(address _t) external {
        target = C(_t);
    }

    receive() external payable {
        // during the external call back to this contract, reenter addToBalance once
        // attempt to reenter only if target has nonzero balance for this attacker to avoid wasting gas
        // we make a low-cost call that may succeed or revert; it's the possibility of reentrancy that matters
        // call without value to reenter
        // Use a try/catch to avoid bubbling reverts
        try target.addToBalance{value: 0}() {
            // ignore
        } catch {
            // ignore
        }
    }
}

