contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: an amount and an address for an attacker helper selector
    function testFuzz_property(uint256 amount, uint64 attackerType) public {
        // keep amount in a reasonable range so vm.deal works and not zero
        amount = bound(amount, 1, 1 ether);

        // Deploy two benign users and one adversarial helper depending on attackerType
        address userA = address(0xA1);
        address userB = address(0xB2);
        vm.deal(userA, amount);
        vm.deal(userB, amount);

        // We need an adversarial counterparty that can reenter during addToBalance via its receive
        // Deploy attacker helper (payable fallback/receive) which will try to reenter and call withdrawBalance
        Attacker attacker = new Attacker(c);
        // fund attacker externally so it can send value when pranked
        vm.deal(address(attacker), amount);

        // Record invariant baseline: before interactions, contract holds 0 and sum balances 0
        assertTrue(address(c).balance == 0);

        // 1) userA deposits normally
        vm.prank(userA);
        c.addToBalance{value: amount}();

        // 2) adversary deposits; during its deposit, its receive may reenter and withdraw or manipulate balances
        // We route the deposit through the attacker contract by having the attacker call c.addToBalance
        // attacker will use its own balance to call
        try attacker.doDeposit{value: amount}() {
