import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz params: depositor (who calls addToBalance) and amount to deposit
    // We must also deploy an attacker contract that when it receives Ether will re-enter C.addToBalance
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor non-zero and amount small enough to fund
        vm.assume(depositor != address(0));
        amount = bound(amount, 1, 1 ether);

        // Deploy attacker and fund it
        Attacker attacker = new Attacker(c);
        vm.deal(address(attacker), 2 ether);
        vm.deal(depositor, 2 ether);

        // Choose a victim address whose balance should not be changed by depositor's addToBalance
        address victim = address(0xBEEF);
        // ensure victim is distinct from depositor and attacker
        vm.assume(victim != depositor && victim != address(attacker));

        // Record victim balance before
        uint256 beforeVictim = c.getBalance(victim);

        // Make the attacker the callee of a low-level call by having the depositor send to attacker,
        // but to trigger the bug we need attacker to re-enter C.addToBalance during depositor's addToBalance.
        // We'll have depositor call C.addToBalance, but the attacker will be the msg.sender for a nested
        // reentrant call only if attacker can be called from within C during the deposit. To ensure that,
        // we first register some funds to attacker so attacker has incentive/state; however the real vector is
        // that attacker will be the depositor here: the fuzzer chooses depositor, but attacker can be used by
        // transferring control via vm.prank. To satisfy the requirement that the fuzz picks the deciding values,
        // we keep depositor as fuzz param and still use attacker to re-enter.

        // Strategy: have depositor call addToBalance normally, but we instruct the attacker to target `victim`
        // during reentrancy. The attacker will attempt to call c.addToBalance{value: amount/2} when it receives
        // Ether; to provoke that, we make depositor first send some Ether to attacker via a plain transfer from depositor,
        // then depositor calls c.addToBalance which will not call attacker. To ensure reentrancy occurs during addToBalance,
        // we instead have depositor be the attacker via vm.startPrank: the fuzzer-chosen depositor will call c.addToBalance,
        // and within C the attacker contract will be triggered by using a specially crafted fallback that gets invoked
        // only if C itself calls out; however C.addToBalance doesn't call external addresses. The reentrancy vector here is
        // that the buggy modifier unlocks during the body, enabling an external call from within the function to re-enter —
        // in the given contract the only external call in the unit is in withdrawBalance. To exploit the buggy modifier during
        // addToBalance we need the attacker to re-enter in some way that the correct contract would prevent. The minimal
        // demonstration is to have the depositor be the attacker contract itself, so that when it calls addToBalance the attacker
        // contract's fallback/receive can invoke another C call (e.g., withdrawBalance) to manipulate balances of victim.

