        // deploy attacker contract at unpredictable address by using salt for deterministic create2-like variability
        Attacker attacker = new Attacker{value: 0}();

        // fund attacker externally so it can deposit
        address attackerAddr = address(attacker);
        vm.deal(attackerAddr, amount);

        // attacker deposits funds by calling addToBalance
        vm.prank(attackerAddr);
        c.addToBalance{value: amount}();

        // now attacker calls withdrawBalance which in the mutant can reenter during the external call
        // Attackers' receive will reenter and perform another withdraw if reentry is possible.
        // After withdrawBalance() returns in the correct contract, address(c).balance must be 0.
        vm.prank(attackerAddr);
        try c.withdrawBalance() {
            // ok
        } catch {
            // even if it reverts somewhere, we proceed to assert on contract balance behavior
        }

        // GENERAL FACT: reference contract prevents reentrancy so after withdraw the contract balance is zero
        // The mutant without the lock can be reentered to leave nonzero balance for some inputs.
        assertTrue(address(c).balance == 0);
    }
}

// Minimal attacker that reenters on receive
contract Attacker {
    bool entered;
    receive() external payable {
        // try to reenter only once to avoid infinite recursion
        if (!entered) {
            entered = true;
            // call back into C.withdrawBalance() on the caller (which is the target contract)
            // We obtain the target as msg.sender of the initial external call — in the withdraw flow,
            // the C contract is the caller of this receive, so we can call it back.
            // We encode a low-level call to attempt reentry.
            (bool s, ) = msg.sender.call(abi.encodeWithSignature("withdrawBalance()"));
            s; // ignore return
        }
    }
}

