pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz params: attacker address (will deploy helper and use its address), deposit amount
    function testFuzz_property(address attackerEOA, uint256 deposit) public {
        // keep wide bounds but ensure nonzero deposit within reasonable test gas limits
        vm.assume(attackerEOA != address(0));
        uint256 amt = bound(deposit, 1, 1 ether);

        // Deploy a reentrant helper that will attempt to reenter withdrawBalance when receiving funds
        ReentrantAttacker attacker = new ReentrantAttacker(address(c));

        // Fund the EOA so it can forward to attacker contract if needed (we will use attacker contract directly)
        vm.deal(address(attacker), amt);

        // Have attacker deposit into c
        vm.prank(address(attacker));
        c.addToBalance{value: amt}();

        // Now trigger withdraw from attacker contract which will reenter
        // Capture whether withdraw completed without revert
        bool ok;
        try attacker.triggerWithdraw{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The general invariant we assert on the reference contract:
        // after withdrawBalance completes for the attacker, the stored balance for that attacker must be 0
        // (read via public getter getBalance). This holds on the correct contract for all inputs,
        // but the mutant (zeroing before external call or vulnerable to reentrancy) will allow a reentrant
        // attack to make attacker obtain funds while leaving state inconsistent, so for some fuzz inputs
        // the mutant will not satisfy this assertion.
        assertTrue(c.getBalance(address(attacker)) == 0);
    }
}

// Minimal re-entrant attacker: on receiving funds it will call withdrawBalance again
contract ReentrantAttacker {
    C target;
    bool entered;
    constructor(address _c) {
        target = C(_c);
        entered = false;
    }

    // deposit handling: this will call back into target.withdrawBalance to attempt reentrancy
    receive() external payable {
        if (!entered) {
            entered = true;
            // attempt reentrancy
            try target.withdrawBalance() {
            } catch {
            }
        }
    }

    // helper to trigger withdraw from this contract
    function triggerWithdraw() external {
        // call withdraw on target as this contract
        target.withdrawBalance();
    }
}
